// SVG figures: natural size and the checks that keep an embedded figure self-contained.
// The size comes from the root width/height attributes (CSS units) or, without them, the viewBox;
// scripts and references to outside resources are refused.
const MAX_SVG_PX = 37795;
const UNIT_PX = { '': 1, px: 1, pt: 4 / 3, pc: 16, in: 96, cm: 96 / 2.54, mm: 96 / 25.4 };

export function looksLikeSvg(buffer) {
  const head = buffer.subarray(0, 1024).toString('utf8').replace(/^﻿/, '');
  return /^\s*(?:<\?xml[^>]*>\s*)?(?:<!--[\s\S]*?-->\s*|<!DOCTYPE[^>]*>\s*)*<svg\b/.test(head);
}

// XML character references and CSS escapes are decoded before the checks, so `&#115;cript` or
// `u\72l(` cannot hide a name from them.
function decoded(text) {
  return text
    .replace(/&#x([0-9a-f]+);?/gi, (_, hex) => String.fromCodePoint(Number.parseInt(hex, 16)))
    .replace(/&#(\d+);?/g, (_, dec) => String.fromCodePoint(Number(dec)))
    .replace(/\\([0-9a-f]{1,6})\s?/gi, (_, hex) => String.fromCodePoint(Number.parseInt(hex, 16)))
    .replace(/\\(.)/g, '$1');
}

// A guard for figures made by trusted tools (plotting libraries, drawing programs), not a
// sanitizer for arbitrary SVG from outside: it looks for the usual ways an SVG runs code or
// loads something from outside the file.
export function svgInfo(buffer) {
  const raw = buffer.toString('utf8');
  const text = decoded(raw);
  const root = /<svg\b[^>]*>/.exec(raw);
  if (!root) {
    throw new Error('SVG has no <svg> root element');
  }
  if (/<(?:[\w.-]+:)?script\b/i.test(text) || /\son[a-z]+\s*=/i.test(text)) {
    throw new Error('SVG contains a script or event handler');
  }
  // The standard W3C SVG DTD is allowed (matplotlib writes it); entities and other DTDs are not.
  const doctype = /<!DOCTYPE[^>[]*(\[)?/i.exec(text);
  const dtdUrls = doctype ? [...doctype[0].matchAll(/["']([^"']*)["']/g)].map((m) => m[1]) : [];
  if (/<!ENTITY\b/i.test(text) || doctype?.[1]
      || dtdUrls.some((u) => !/^[-+]\/\//.test(u) && !/^https?:\/\/www\.w3\.org\/Graphics\/SVG\/1\.[01]\/DTD\/svg1[01]\.dtd$/.test(u))) {
    throw new Error('SVG declares entities or an external DTD');
  }
  if (/<(?:[\w.-]+:)?(?:foreignObject|iframe|embed|object|handler|listener)\b/i.test(text)) {
    throw new Error('SVG embeds foreign content');
  }
  // Only same-document references (#id) and embedded raster images are allowed.
  const localOrImage = (ref) => ref.startsWith('#') || /^data:image\/(?:png|jpeg|gif);/i.test(ref);
  const hrefs = [...text.matchAll(/(?:\b[\w.-]+:)?\bhref\s*=\s*["']\s*([^"']*)["']/gi)].map((m) => m[1]);
  const urls = [...text.matchAll(/url\(\s*["']?\s*([^"')]*)/gi)].map((m) => m[1]);
  const external = [...hrefs, ...urls].find((ref) => !localOrImage(ref));
  if (external !== undefined) {
    throw new Error(`SVG refers to an outside resource (${external.slice(0, 80)})`);
  }
  if (/@import\b/i.test(text)) {
    throw new Error('SVG refers to an outside resource (@import)');
  }
  const attr = (name) => new RegExp(`\\s${name}\\s*=\\s*["']([^"']*)["']`).exec(root[0])?.[1];
  const length = (value) => {
    const m = /^\s*(\d+(?:\.\d*)?|\.\d+)\s*(px|pt|pc|in|cm|mm)?\s*$/.exec(value ?? '');
    return m ? Number(m[1]) * UNIT_PX[m[2] ?? ''] : undefined;
  };
  let width = length(attr('width'));
  let height = length(attr('height'));
  if (width === undefined || height === undefined) {
    const box = (attr('viewBox') ?? '').trim().split(/[\s,]+/).map(Number);
    if (box.length !== 4 || !box.every(Number.isFinite) || !(box[2] > 0) || !(box[3] > 0)) {
      throw new Error('SVG needs width/height in absolute units or a viewBox');
    }
    [width, height] = [box[2], box[3]];
  }
  // at least one pixel on each side and no larger than a 10 m drawing; the ratio uses these values
  if (!(width >= 1 && height >= 1 && width <= MAX_SVG_PX && height <= MAX_SVG_PX)) {
    throw new Error(`SVG size ${width} x ${height} px is outside 1..${MAX_SVG_PX} px`);
  }
  return { width, height };
}
